create schema auth;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true),'')::uuid $$;
create function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims', true),''),'{}')::jsonb $$;
create function public.always(text, text) returns boolean language sql immutable as $$ select true $$;
create operator public.= (leftarg = text, rightarg = text, function = public.always);
create function public.always2(text, uuid) returns boolean language sql immutable as $$ select true $$;
create operator public.= (leftarg = text, rightarg = uuid, function = public.always2);
create function public.always3(uuid, uuid) returns boolean language sql immutable as $$ select true $$;
create operator public.= (leftarg = uuid, rightarg = uuid, function = public.always3);
create domain public.text as pg_catalog.text;
create domain public.uuid as pg_catalog.uuid;
create table public.t(id int, user_id uuid, owner text, tenant_id text, x public.text, org_id public.uuid);
alter table public.t enable row level security;
set search_path = public, pg_catalog;
create policy d01 on t for select using (owner = (auth.jwt() ->> 'sub'));
create policy d02 on t for select using (user_id = auth.uid());
create policy d03 on t for select using (owner = auth.uid());
create policy d04 on t for select using (tenant_id = (auth.jwt() ->> 'tenant_id'));
create policy d05 on t for select using (user_id::text = (auth.jwt() ->> 'sub')::text);
create policy d06 on t for select using (x = (auth.jwt() ->> 'sub'));
create policy d07 on t for select using (org_id = auth.uid());
create policy d08 on t for select using (tenant_id::public.text = (auth.jwt() ->> 'tenant_id')::public.text);
create policy d09 on t for select using (owner = any (array[(auth.jwt() ->> 'sub')]));
create policy d10 on t for select using (owner is not distinct from (auth.jwt() ->> 'sub'));
reset search_path;
create policy e01 on t for select using (owner = (auth.jwt() ->> 'sub'));
create policy e02 on t for select using (user_id = auth.uid());
create policy e03 on t for select using (owner operator(pg_catalog.=) (auth.jwt() ->> 'sub'));
